"""A partial-roster resident is reserved like a complete-read one (#4967).

Local ch10 (g1190-ch1v4 46-7 step 937616): アルマムーン held many generals but
its list was only partially read (garrison_partial), several castles were lost,
and the first five retake orders all named ブカティーニ — the later castles
stalled after the first sortie because planned_busy never got the general.
"""
from docich.hanjuku_speedrun.hanjuku.strategy import replan
from docich.hanjuku_speedrun.hanjuku.state.regions import world as _world


def partial_home():
    mem = {
        'chapter': 5, 'month': '42-6', 'tick': 100774,
        'captured': ['テラビル', 'ヒュペルボレア', 'ボッサール', 'アイアイア',
                     'バスカビル', 'プトレマイス', 'オトラント'],
        'lost': ['ジュメルズ', 'クロチェット', 'カルーン'],
        'orders': {},
        'garrison': {
            'アイアイア': [],
            'アルマムーン': None,          # only a partial page was read
            'オトラント': ['マンゴスチン'], 'テラビル': ['リースリング'],
            'バスカビル': ['マカデミア'], 'ヒュペルボレア': ['ピスタチオ'],
            'プトレマイス': ['キャンディー'], 'ボッサール': ['ポセイドン'],
        },
        'route_probe_read_tick': {'アイアイア': 100774},
        'sorties': {}, 'launched_orders': {}, '_records': [],
        'house_eggs': {}, 'general_location_unknown': [],
    }
    _world(mem)['garrison_partial'] = {
        'アルマムーン': ['ブカティーニ', 'ライム', 'マーマレード', 'どうし',
                         'ペコリーノ', 'クランベリー'],
    }
    return mem


def retakes(mem):
    lost = set(mem['lost'])
    return [order for order in replan.interim_candidates(mem).values()
            if order.get('purpose') == 'retake' and order.get('target') in lost]


def test_partial_roster_generals_are_not_reused_across_retakes():
    orders = retakes(partial_home())
    generals = [order['general'] for order in orders]
    assert orders
    assert len(generals) == len(set(generals))
